// Contract logic tests for SimpleNFT.
//
// These run the REAL contract (`NFTExample.runar.rs`, included below via
// `#[path]`), not a copy of it. They used to run an inline re-implementation:
// a struct + impl typed out again in this file, so deleting or breaking the
// shipped contract's logic left every test green (F-057).
//
// `self.add_output(...)` is generated by `#[runar::contract]`; it records each
// output on a thread-local log that `SimpleNFT::take_outputs()` drains. Each
// `#[test]` runs on its own thread, so the log starts empty in every test.
//
// What these prove: the shipped `transfer` / `burn` bodies, compiled as native
// Rust against the `runar` mocks (real ECDSA over the fixed test message),
// produce the outputs asserted below. What they do not prove: anything about
// the compiled Bitcoin Script — `test_compile` only runs the Rúnar frontend,
// and on-chain behaviour is the job of the Spend-based suites.

#[path = "NFTExample.runar.rs"]
mod contract;

use contract::*;
use runar::prelude::*;

fn alice() -> PubKey { ALICE.pub_key.to_vec() }
fn bob() -> PubKey { BOB.pub_key.to_vec() }
fn charlie() -> PubKey { CHARLIE.pub_key.to_vec() }

fn new_nft(owner: PubKey) -> SimpleNFT {
    SimpleNFT {
        owner,
        token_id: b"unique-nft-001".to_vec(),
        metadata: b"ipfs://QmTest".to_vec(),
    }
}

#[test]
fn test_transfer() {
    let mut c = new_nft(alice());
    c.transfer(&ALICE.sign_test_message(), bob(), 1000);
    // token_id and metadata are readonly: transfer must not touch them.
    assert_eq!(c.token_id, b"unique-nft-001".to_vec());
    assert_eq!(c.metadata, b"ipfs://QmTest".to_vec());
    let outputs = SimpleNFT::take_outputs();
    assert_eq!(outputs.len(), 1);
    assert_eq!(outputs[0].owner, bob());
    assert_eq!(outputs[0].satoshis, 1000);
}

#[test]
fn test_transfer_chain() {
    let mut c = new_nft(alice());
    c.transfer(&ALICE.sign_test_message(), bob(), 1000);
    assert_eq!(SimpleNFT::take_outputs()[0].owner, bob());
    // The successor UTXO is owned by bob; model spending it.
    c.owner = bob();
    c.transfer(&BOB.sign_test_message(), charlie(), 1000);
    let outputs = SimpleNFT::take_outputs();
    assert_eq!(outputs.len(), 1);
    assert_eq!(outputs[0].owner, charlie());
}

#[test]
fn test_burn() {
    let c = new_nft(alice());
    c.burn(&ALICE.sign_test_message());
    assert_eq!(SimpleNFT::take_outputs().len(), 0);
}

#[test]
fn test_compile() {
    runar::compile_check(include_str!("NFTExample.runar.rs"), "NFTExample.runar.rs").unwrap();
}
